#include <vector>
#include <algorithm>
#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/Orientation_2.h>

typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef K::Point_2 Point_2;

// Helper function to compute orientation
CGAL::Orientation orientation(const Point_2& p, const Point_2& q, const Point_2& r) {
    return CGAL::orientation(p, q, r);
}

// Helper function to compare polar angles
bool compare_polar_angle(const Point_2& pivot, const Point_2& a, const Point_2& b) {
    auto orient = orientation(pivot, a, b);
    if (orient == CGAL::COLLINEAR) {
        // If collinear, choose the closer point first
        auto dist_a = CGAL::squared_distance(pivot, a);
        auto dist_b = CGAL::squared_distance(pivot, b);
        return dist_a < dist_b;
    }
    return orient == CGAL::LEFT_TURN;
}

std::vector<Point_2> convex_hull_graham(std::vector<Point_2> points) {
    if (points.size() <= 1) {
        return points;
    }

    // Find the pivot (lowest y, leftmost if ties)
    auto pivot = *std::min_element(points.begin(), points.end(), [](const Point_2& a, const Point_2& b) {
        return a.y() < b.y() || (a.y() == b.y() && a.x() < b.x());
    });

    // Sort points by polar angle with respect to the pivot
    std::sort(points.begin(), points.end(), [&pivot](const Point_2& a, const Point_2& b) {
        if (a == pivot) return true;
        if (b == pivot) return false;
        return compare_polar_angle(pivot, a, b);
    });

    // Remove collinear points (keep farthest)
    size_t n = points.size();
    if (n <= 2) {
        return points;
    }

    std::vector<Point_2> hull;
    hull.push_back(points[0]);
    hull.push_back(points[1]);

    for (size_t i = 2; i < n; ++i) {
        while (hull.size() >= 2 && 
               orientation(hull[hull.size() - 2], hull.back(), points[i]) != CGAL::LEFT_TURN) {
            hull.pop_back();
        }
        hull.push_back(points[i]);
    }

    return hull;
}

